CREATE OR REPLACE FUNCTION public.qms_complaint_notice_due(p_due timestamp with time zone, p_offset integer, p_type text, p_calendar bigint)
 RETURNS timestamp with time zone
 LANGUAGE plpgsql
 STABLE
 SET search_path TO ''
AS $function$
DECLARE d date := (p_due AT TIME ZONE 'America/Costa_Rica')::date; n integer := 0; safety integer := 0;
BEGIN
 IF p_offset IS NULL THEN RETURN NULL; END IF;
 IF p_offset < 0 OR p_offset > 3660 THEN RAISE EXCEPTION 'Aviso inválido.'; END IF;
 WHILE n < p_offset LOOP
 d := d - 1; safety := safety + 1;
 IF p_type = 'calendar_days' OR public.qms_business_day(d,p_calendar) THEN n := n+1; END IF;
 IF safety > 30000 THEN RAISE EXCEPTION 'Calendario inválido.'; END IF;
 END LOOP;
 RETURN (d + time '06:00') AT TIME ZONE 'America/Costa_Rica';
END;
$function$

CREATE OR REPLACE FUNCTION public.notificar_queja_publica(p_folio text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
 v_queja_id uuid;
 v_categoria text;
 v_staff record;
BEGIN
 SELECT id, categoria INTO v_queja_id, v_categoria
 FROM quejas
 WHERE folio = p_folio
 LIMIT 1;

 IF v_queja_id IS NULL THEN
 RAISE EXCEPTION 'Queja no encontrada para el folio %', p_folio;
 END IF;

 -- Evitar notificaciones duplicadas si el frontend reintenta.
 IF EXISTS (
 SELECT 1 FROM public.notificaciones
 WHERE tipo = 'queja_nueva' AND origen_id = v_queja_id::text
 ) THEN
 RETURN;
 END IF;

 FOR v_staff IN
 SELECT id, email FROM public.usuarios
 WHERE rol IN ('admin', 'calidad')
 AND (estado IS NULL OR estado = 'activo')
 LOOP
 INSERT INTO public.notificaciones (usuario_id, fecha, tipo, mensaje, enlace, origen_id)
 VALUES (
 v_staff.id,
 now(),
 'queja_nueva',
 'Nueva queja ' || p_folio || ' registrada: ' || COALESCE(v_categoria, ''),
 '/quejas',
 v_queja_id::text
 );

 INSERT INTO public.mail_queue (destinatario, asunto, cuerpo, estado, intentos, created_at)
 SELECT v_staff.email, 'Nueva queja ' || p_folio, 'Se recibió una nueva queja con folio ' || p_folio || '.', 'pendiente', 0, now()
 WHERE v_staff.email IS NOT NULL;
 END LOOP;
END;
$function$

CREATE OR REPLACE FUNCTION public.qms_due(p_start timestamp with time zone, p_days integer, p_type text, p_calendar bigint)
 RETURNS timestamp with time zone
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public'
AS $function$
DECLARE d date := (p_start AT TIME ZONE 'America/Costa_Rica')::date; n integer:=0; safety integer:=0;
BEGIN
 IF p_days<1 OR p_days>3660 OR p_type NOT IN ('business_days','calendar_days') THEN RAISE EXCEPTION 'Plazo inválido'; END IF;
 IF NOT EXISTS(SELECT 1 FROM qms_calendars WHERE id=p_calendar) THEN RAISE EXCEPTION 'Calendario no encontrado'; END IF;
 WHILE n<p_days LOOP
 d:=d+1; safety:=safety+1;
 IF p_type='calendar_days' OR qms_business_day(d,p_calendar) THEN n:=n+1; END IF;
 IF safety>30000 THEN RAISE EXCEPTION 'El calendario no permite calcular el vencimiento'; END IF;
 END LOOP;
 WHILE NOT qms_business_day(d,p_calendar) LOOP
 d:=d+1; safety:=safety+1;
 IF safety>30000 THEN RAISE EXCEPTION 'El calendario no permite calcular el vencimiento'; END IF;
 END LOOP;
 RETURN (d+1)::timestamp AT TIME ZONE 'America/Costa_Rica' - interval '1 microsecond';
END; $function$

CREATE OR REPLACE FUNCTION public.qms_sync_queja()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE stage text; active_run public.qms_stage_runs; rule public.qms_stage_versions;
 cal bigint; run uuid; due timestamptz; alert integer; attention timestamptz;
BEGIN
 IF TG_OP = 'UPDATE' THEN
 NEW.revision := OLD.revision + 1;
 NEW.fecha_sla := OLD.fecha_sla;
 NEW.fecha_limite_investigacion := OLD.fecha_limite_investigacion;
 IF NEW.estado IS NOT DISTINCT FROM OLD.estado THEN RETURN NEW; END IF;

 -- La revisión GC es parte de la misma investigación: no detener ni reiniciar sus 15 días.
 IF OLD.estado IN ('En Investigación','Pendiente de Revisión GC')
 AND NEW.estado IN ('En Investigación','Pendiente de Revisión GC') THEN
 SELECT * INTO active_run FROM public.qms_stage_runs
 WHERE case_id = NEW.id AND stage_id = 'quejas.investigation'
 AND ended_at IS NULL ORDER BY started_at DESC LIMIT 1;
 IF active_run.id IS NULL AND OLD.estado = 'Pendiente de Revisión GC' THEN
 -- Recupera solamente el snapshot que el trigger anterior cerró al enviar a GC.
 SELECT * INTO active_run FROM public.qms_stage_runs
 WHERE case_id = NEW.id AND stage_id = 'quejas.investigation'
 AND end_event = 'Pendiente de Revisión GC' ORDER BY ended_at DESC LIMIT 1 FOR UPDATE;
 IF active_run.id IS NOT NULL THEN
 UPDATE public.qms_stage_runs SET ended_at = NULL, end_event = NULL WHERE id = active_run.id;
 END IF;
 END IF;
 IF active_run.id IS NOT NULL THEN NEW.fecha_limite_investigacion := active_run.expires_at; END IF;
 RETURN NEW;
 END IF;
 UPDATE public.qms_stage_runs SET ended_at = now(), end_event = NEW.estado
 WHERE case_id = NEW.id AND ended_at IS NULL;
 END IF;
 stage := CASE NEW.estado WHEN 'Recibido' THEN 'quejas.evaluation'
 WHEN 'En Investigación' THEN 'quejas.investigation' END;
 IF stage IS NULL THEN RETURN NEW; END IF;
 PERFORM pg_advisory_xact_lock_shared(hashtextextended('qms.config', 0));
 SELECT * INTO rule FROM public.qms_stage_versions WHERE stage_id = stage ORDER BY id DESC LIMIT 1;
 SELECT id INTO cal FROM public.qms_calendars ORDER BY id DESC LIMIT 1;
 IF rule.id IS NULL OR cal IS NULL THEN RAISE EXCEPTION 'Falta configurar el plazo y el calendario.' USING ERRCODE = '22023'; END IF;
 due := public.qms_due(now(), rule.duration, rule.day_type, cal);
 SELECT public.qms_complaint_notice_due(due, max(a), rule.day_type, cal)
 INTO attention FROM unnest(rule.alerts) a;
 INSERT INTO public.qms_stage_runs(case_id,stage_id,rule_id,calendar_id,snapshot,started_at,expires_at,attention_at)
 VALUES(NEW.id,stage,rule.id,cal,jsonb_build_object('rule',to_jsonb(rule),
 'calendar',(SELECT to_jsonb(c) FROM public.qms_calendars c WHERE c.id = cal)),now(),due,attention)
 RETURNING id INTO run;
 FOREACH alert IN ARRAY rule.alerts LOOP
 INSERT INTO public.qms_deadline_notices(run_id,offset_days,due_at)
 VALUES(run,alert,public.qms_complaint_notice_due(due, alert, rule.day_type, cal));
 END LOOP;
 IF rule.expiration_action = 'notify_quality' THEN
 INSERT INTO public.qms_deadline_notices(run_id,offset_days,due_at) VALUES(run,0,due + interval '1 microsecond');
 END IF;
 IF stage = 'quejas.evaluation' THEN NEW.fecha_sla := due; ELSE NEW.fecha_limite_investigacion := due; END IF;
 RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.qms_process_notices()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE n record; delivered integer:=0;
BEGIN
 FOR n IN SELECT a.*,r.case_id,r.ended_at FROM qms_deadline_notices a JOIN qms_stage_runs r ON r.id=a.run_id
 WHERE a.processed_at IS NULL AND a.due_at<=now() ORDER BY a.due_at LIMIT 250 FOR UPDATE OF a SKIP LOCKED LOOP
 PERFORM 1 FROM qms_stage_runs WHERE id=n.run_id AND ended_at IS NULL FOR SHARE;
 IF FOUND THEN
 INSERT INTO notificaciones(usuario_id,fecha,tipo,mensaje,enlace,origen_id)
 SELECT u.id,now(),'qms_plazo',CASE WHEN n.offset_days=0 THEN 'Plazo vencido: ' ELSE 'Próximo vencimiento: ' END||q.folio,
 '/quejas',q.id FROM usuarios u JOIN quejas q ON q.id=n.case_id
 WHERE u.estado='activo' AND (u.rol IN ('admin','calidad') OR u.id=q.responsable_id);
 delivered:=delivered+1;
 END IF;
 UPDATE qms_deadline_notices SET processed_at=now() WHERE id=n.id;
 END LOOP;
 RETURN delivered;
END; $function$

CREATE OR REPLACE FUNCTION public.qms_enqueue_complaint_mail()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE kind text; recipient text;
BEGIN
 IF TG_OP = 'INSERT' AND NEW.estado = 'Recibido' THEN kind := 'recibido';
 ELSIF TG_OP = 'UPDATE' AND NEW.estado IS DISTINCT FROM OLD.estado THEN
 kind := CASE WHEN NEW.estado = 'En Investigación' THEN 'investigacion'
 WHEN NEW.estado IN ('Resuelto','No Procede') THEN 'final' END;
 END IF;
 IF kind IS NULL THEN RETURN NEW; END IF;
 recipient := lower(btrim(coalesce(NEW.email_cliente,'')));
 -- Históricos sin dirección válida siguen editables; no crear un envío incorrecto.
 IF length(recipient) NOT BETWEEN 3 AND 254 OR
 recipient !~ '^[^[:space:]@,;<>]+@[^[:space:]@,;<>]+\.[^[:space:]@,;<>]+$' THEN RETURN NEW; END IF;
 INSERT INTO public.queja_mail_outbox(queja_id,tipo,destinatario,folio,estado,numero_oficio)
 VALUES(NEW.id,kind,recipient,NEW.folio,NEW.estado,NEW.numero_oficio_resolucion)
 ON CONFLICT (queja_id,tipo) DO NOTHING;
 RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.qms_mail_complete(p_id uuid, p_claim_token uuid, p_outcome text, p_retry_delay_seconds integer, p_safe_error text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE affected integer;
BEGIN
 IF p_outcome IS NULL OR p_outcome NOT IN ('sent','retry','uncertain','failed')
 OR p_retry_delay_seconds IS NULL OR p_retry_delay_seconds NOT BETWEEN 60 AND 86400
 OR (p_safe_error IS NOT NULL AND p_safe_error !~ '^[a-z_]{1,60}$') THEN
 RAISE EXCEPTION 'Resultado de worker inválido.' USING ERRCODE = '22023';
 END IF;
 UPDATE public.queja_mail_outbox o SET status=p_outcome,
 next_attempt_at=CASE WHEN p_outcome='retry' THEN now()+make_interval(secs=>p_retry_delay_seconds) ELSE o.next_attempt_at END,
 sent_at=CASE WHEN p_outcome='sent' THEN now() ELSE o.sent_at END,
 safe_error=CASE WHEN p_outcome='sent' THEN NULL ELSE p_safe_error END,
 claim_token=NULL,lease_until=NULL,updated_at=now()
 WHERE o.id=p_id AND o.claim_token=p_claim_token AND o.status='leased' AND o.lease_until > now();
 GET DIAGNOSTICS affected = ROW_COUNT;
 RETURN affected = 1;
END;
$function$

CREATE OR REPLACE FUNCTION public.qms_mail_claim_batch(p_limit integer, p_lease_seconds integer, p_run_nonce uuid, p_issued_at bigint)
 RETURNS TABLE(id uuid, claim_token uuid, tipo text, destinatario text, folio text, estado text, numero_oficio text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE inserted integer; moment bigint := floor(extract(epoch FROM now()))::bigint;
BEGIN
 IF p_limit IS NULL OR p_limit NOT BETWEEN 1 AND 5 OR p_lease_seconds IS NULL OR p_lease_seconds NOT BETWEEN 60 AND 600
 OR p_run_nonce IS NULL OR p_issued_at IS NULL OR p_issued_at < moment - 300 OR p_issued_at > moment + 30 THEN
 RAISE EXCEPTION 'Solicitud de worker inválida.' USING ERRCODE = '22023';
 END IF;
 DELETE FROM public.queja_mail_run_nonces WHERE nonce IN
 (SELECT n.nonce FROM public.queja_mail_run_nonces n WHERE n.expires_at < now() ORDER BY n.expires_at LIMIT 1000);
 INSERT INTO public.queja_mail_run_nonces VALUES(p_run_nonce,now()+interval '10 minutes')
 ON CONFLICT (nonce) DO NOTHING;
 GET DIAGNOSTICS inserted = ROW_COUNT;
 IF inserted = 0 THEN RETURN; END IF;
 -- Un lease vencido no demuestra que el proveedor no envió. Revisión, nunca reenvío ciego.
 UPDATE public.queja_mail_outbox o SET status='uncertain',safe_error='lease_expired',updated_at=now()
 WHERE o.status='leased' AND o.lease_until <= now();
 UPDATE public.queja_mail_outbox o SET status='failed',safe_error='attempt_limit',updated_at=now()
 WHERE o.status IN ('pending','retry') AND o.attempts >= 12;
 RETURN QUERY WITH candidates AS (
 SELECT o.id FROM public.queja_mail_outbox o
 WHERE o.status IN ('pending','retry') AND o.next_attempt_at <= now() AND o.attempts < 12
 AND NOT EXISTS (SELECT 1 FROM public.queja_mail_outbox prior WHERE prior.queja_id=o.queja_id
 AND prior.status <> 'sent'
 AND CASE prior.tipo WHEN 'recibido' THEN 1 WHEN 'investigacion' THEN 2 ELSE 3 END
 < CASE o.tipo WHEN 'recibido' THEN 1 WHEN 'investigacion' THEN 2 ELSE 3 END)
 ORDER BY o.next_attempt_at,o.id FOR UPDATE SKIP LOCKED LIMIT p_limit
 ), claimed AS (
 UPDATE public.queja_mail_outbox o SET status='leased',claim_token=gen_random_uuid(),
 lease_until=now()+make_interval(secs=>p_lease_seconds),attempts=o.attempts+1,updated_at=now()
 FROM candidates c WHERE o.id=c.id RETURNING o.*
 ) SELECT c.id,c.claim_token,c.tipo,c.destinatario,c.folio,c.estado,c.numero_oficio FROM claimed c;
END;
$function$
